def run(env):
    while True:
        context = env.component("context_full")
        decision = env.component("decide", context=context["id"])
        if decision["value"]["kind"] == "completion_proposed":
            return decision["value"]["response"]
        execution = env.component("execute", decision=decision["id"])
        env.component("observe_full", execution=execution["id"])

def run(env):
    base = None
    observed = 0
    while True:
        if base is None:
            context = env.component("context_full")
        else:
            context = env.component("context_full", base=base)
        if observed == 8:
            context = env.component("context_summary", context=context["id"])
            base = context["id"]
            observed = 0
        decision = env.component("decide", context=context["id"])
        if decision["value"]["kind"] == "completion_proposed":
            return decision["value"]["response"]
        execution = env.component("execute", decision=decision["id"])
        env.component("observe_full", execution=execution["id"])
        observed += 1

def run(env):
    base = None
    observed = 0
    while True:
        if base is None:
            context = env.component("context_full")
        else:
            context = env.component("context_full", base=base)
        compressed = observed == 8
        if compressed:
            context = env.component("context_summary", context=context["id"])
            base = context["id"]
            observed = 0
        decision = env.component("decide", context=context["id"])
        if compressed:
            original = env.component("context_full")
            review = env.component("critique", context=original["id"], target=decision["id"])
            if review["value"]["verdict"] != "supported":
                revised_context = env.component("context_full")
                decision = env.component("decide", context=revised_context["id"], inputs=[review["id"]])
        if decision["value"]["kind"] == "completion_proposed":
            return decision["value"]["response"]
        execution = env.component("execute", decision=decision["id"])
        env.component("observe_full", execution=execution["id"])
        observed += 1
